+        try {
+            Class<?> strategyType = Class.forName(configured);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyType)) {
+                throw new Exception("type does not implement RuleViolationFileNameStrategy");
+            }
+            Constructor<?> constructor = strategyType.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate %s configured by %s=%s; the value must be random, description, or a RuleViolationFileNameStrategy with a public no-argument constructor",
+                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, configured), e);
+        }
+    }
