+    private File getStoredRulesFile() {
+        File rulesFile = new File(storeFolder, STORED_RULES_FILE_NAME);
+        if (!Files.exists(rulesFile.toPath(), LinkOption.NOFOLLOW_LINKS) && !storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+        return rulesFile;
+    }
+
+    private void ensureStoreFolderExists() {
+        try {
+            Files.createDirectories(storeFolder.toPath());
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        if (!Files.isDirectory(storeFolder.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot use violation store folder %s because it is not a directory", storeFolder.getAbsolutePath()));
+        }
+    }
+
+    private Object lockFor(File folder) {
+        try {
+            String path = folder.getCanonicalPath();
+            return STORE_LOCKS_BY_PATH.computeIfAbsent(path, ignored -> new Object());
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private FileSyncedProperties getOrCreateStoredRules(File storedRulesFile) {
+        try {
+            return STORED_RULES_BY_PATH.computeIfAbsent(storedRulesFile.getCanonicalPath(),
+                    ignored -> new FileSyncedProperties(storedRulesFile));
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
