+            if (!shared && sourceExists) {
+                deleteOwnedFile(source);
+            }
+            moveReplacing(indexTemp, getStoredRulesFile().toPath());
+            storedRules.replaceLoaded(next);
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        } finally {
+            deleteQuietly(indexTemp);
+        }
+    }
