+/**
+ * A text file based implementation of a {@link ViolationStore}.<br>
+ * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
+ * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
+ *
+ * <p>The store can be configured through the following properties:</p>
+ * <pre><code>
+ * default.path=...               # string: the path of the folder where violation files will be stored
+ * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
+ * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
+ * default.fileNames=random       # random, description, or a RuleViolationFileNameStrategy class
+ * default.integrity=ignore       # repair, fail, or ignore
+ * </code></pre>
+ */
+@PublicAPI(usage = ACCESS)
+public final class TextFileBasedViolationStore implements ViolationStore {
+    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);
+
+    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
+    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile(
+            "(?<![A-Za-z0-9])([A-Za-z0-9]{4,120})(?![A-Za-z0-9])");
+    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
+    private static final String STORE_PATH_DEFAULT = "archunit_store";
+    private static final String STORED_RULES_FILE_NAME = "stored.rules";
+    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
+    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
+    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
+    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
+    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
+    private static final String FILE_NAMES_RANDOM = "random";
+    private static final String FILE_NAMES_DESCRIPTION = "description";
+    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
+    private static final String INTEGRITY_DEFAULT = "ignore";
+    private static final String INTEGRITY_REPAIR = "repair";
+    private static final String INTEGRITY_FAIL = "fail";
+    private static final String INTEGRITY_IGNORE = "ignore";
+
+    /* Both maps deliberately live for the lifetime of the process. A store can be initialized again after another
+       instance has saved, so FileSyncedProperties is refreshed on every initialization. */
+    private static final ConcurrentHashMap<String, FileSyncedProperties> STORED_RULES_BY_PATH = new ConcurrentHashMap<>();
+    private static final ConcurrentHashMap<String, Object> STORE_LOCKS_BY_PATH = new ConcurrentHashMap<>();
+
+    private final RuleViolationFileNameStrategy constructorStrategy;
+    private final boolean usesConstructorStrategy;
+
+    private RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
+    private IntegrityMode integrityMode;
+    private boolean storeCreationAllowed;
+    private boolean storeUpdateAllowed;
+    private File storeFolder;
+    private FileSyncedProperties storedRules;
+    private Object storeLock;
+
+    /**
+     * Creates a standard {@link TextFileBasedViolationStore} that names rule violation files by random {@link UUID}s.
+     */
+    public TextFileBasedViolationStore() {
+        constructorStrategy = null;
+        usesConstructorStrategy = false;
+    }
+
+    /**
+     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming.
+     *
+     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
+     */
+    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
+        if (ruleViolationFileNameStrategy == null) {
+            throw new NullPointerException("ruleViolationFileNameStrategy must not be null");
+        }
+        constructorStrategy = ruleViolationFileNameStrategy;
+        usesConstructorStrategy = true;
+    }
+
+    @Override
+    public void initialize(Properties properties) {
+        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(
+                ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(
+                ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        integrityMode = parseIntegrity(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
+        ruleViolationFileNameStrategy = configureFileNameStrategy(properties);
+
+        storeFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
+        storeLock = lockFor(storeFolder);
+        synchronized (storeLock) {
+            if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Integrity repair requires updating the store (enable by configuration %s.%s=true)",
+                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+            }
+
+            File storedRulesFile = getStoredRulesFile();
+            log.trace("Initializing {} at {}", TextFileBasedViolationStore.class.getSimpleName(),
+                    storedRulesFile.getAbsolutePath());
+
+            boolean indexPresent = Files.exists(storedRulesFile.toPath(), LinkOption.NOFOLLOW_LINKS);
+            if (!indexPresent) {
+                ensureStoreFolderExists();
+            } else if (!Files.isDirectory(storeFolder.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Cannot use violation store folder %s because it is not a directory", storeFolder.getAbsolutePath()));
+            }
+
+            if (Files.exists(storedRulesFile.toPath(), LinkOption.NOFOLLOW_LINKS)
+                    && !Files.isRegularFile(storedRulesFile.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Violation store index %s must be a regular file directly in the store folder",
+                        storedRulesFile.getAbsolutePath()));
+            }
+
+            storedRules = getOrCreateStoredRules(storedRulesFile);
+            Properties current = indexPresent ? loadRulesFrom(storedRulesFile) : new Properties();
+
+            if (integrityMode == IntegrityMode.IGNORE) {
+                if (!indexPresent) {
+                    writeIndexForInitialization(storedRulesFile, current);
+                }
+                storedRules.replaceLoaded(current);
+                return;
+            }
+
+            IntegrityReport report = inspect(current);
+            if (integrityMode == IntegrityMode.FAIL && report.hasProblems()) {
+                throw new StoreInitializationFailedException(report.message(storedRulesFile));
+            }
+
+            if (integrityMode == IntegrityMode.REPAIR) {
+                Properties repaired = copyOf(current);
+                boolean changed = repair(report, repaired);
+                if (changed || !indexPresent) {
+                    writeIndexForInitialization(storedRulesFile, repaired);
+                }
+                storedRules.replaceLoaded(repaired);
+            } else {
+                if (!indexPresent) {
+                    writeIndexForInitialization(storedRulesFile, current);
+                }
+                storedRules.replaceLoaded(current);
+            }
+        }
+    }
+
+    private IntegrityMode parseIntegrity(String value) {
+        if (INTEGRITY_REPAIR.equals(value)) {
+            return IntegrityMode.REPAIR;
+        }
+        if (INTEGRITY_FAIL.equals(value)) {
+            return IntegrityMode.FAIL;
+        }
+        if (INTEGRITY_IGNORE.equals(value)) {
+            return IntegrityMode.IGNORE;
+        }
+        throw new StoreInitializationFailedException(String.format(
+                "Invalid %s value '%s'; accepted values are repair, fail and ignore",
+                INTEGRITY_PROPERTY_NAME, value));
+    }
+
+    private RuleViolationFileNameStrategy configureFileNameStrategy(Properties properties) {
+        if (usesConstructorStrategy) {
+            if (hasProperty(properties, FILE_NAMES_PROPERTY_NAME)) {
+                throw new StoreInitializationFailedException(String.format(
+                        "%s cannot be configured when a RuleViolationFileNameStrategy was supplied to the constructor",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            return constructorStrategy;
+        }
+
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME, FILE_NAMES_RANDOM);
+        if (FILE_NAMES_RANDOM.equals(configured)) {
+            return description -> UUID.randomUUID().toString();
+        }
+        if (FILE_NAMES_DESCRIPTION.equals(configured)) {
+            return TextFileBasedViolationStore::descriptionFileName;
+        }
+
+        try {
+            Class<?> strategyType = Class.forName(configured);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyType)) {
+                throw new Exception("type does not implement RuleViolationFileNameStrategy");
+            }
+            Constructor<?> constructor = strategyType.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (Exception e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate %s configured by %s=%s; the value must be random, description, or a RuleViolationFileNameStrategy with a public no-argument constructor",
+                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, configured), e);
+        }
+    }
+
+    private boolean hasProperty(Properties properties, String propertyName) {
+        return properties.stringPropertyNames().contains(propertyName);
+    }
+
+    private static String descriptionFileName(String description) {
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
+        String keptWord = null;
+        while (matcher.find()) {
+            keptWord = matcher.group(1);
+        }
+        String hash = sha256(description);
+        return (keptWord == null ? "rule" : keptWord) + "-" + hash;
+    }
+
+    private static String sha256(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder(digest.length * 2);
+            for (byte current : digest) {
+                result.append(String.format("%02x", current & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new IllegalStateException(e);
+        }
+    }
+
+    private File getStoredRulesFile() {
+        File rulesFile = new File(storeFolder, STORED_RULES_FILE_NAME);
+        if (!Files.exists(rulesFile.toPath(), LinkOption.NOFOLLOW_LINKS) && !storeCreationAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+        }
+        return rulesFile;
+    }
+
+    private void ensureStoreFolderExists() {
+        try {
+            Files.createDirectories(storeFolder.toPath());
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        if (!Files.isDirectory(storeFolder.toPath(), LinkOption.NOFOLLOW_LINKS)) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Cannot use violation store folder %s because it is not a directory", storeFolder.getAbsolutePath()));
+        }
+    }
+
+    private Object lockFor(File folder) {
+        try {
+            String path = folder.getCanonicalPath();
+            return STORE_LOCKS_BY_PATH.computeIfAbsent(path, ignored -> new Object());
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private FileSyncedProperties getOrCreateStoredRules(File storedRulesFile) {
+        try {
+            return STORED_RULES_BY_PATH.computeIfAbsent(storedRulesFile.getCanonicalPath(),
+                    ignored -> new FileSyncedProperties(storedRulesFile));
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private Properties loadRulesFrom(File file) {
+        Properties result = new Properties();
+        try (FileInputStream inputStream = new FileInputStream(file)) {
+            result.load(inputStream);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        return result;
+    }
+
+    private void writeIndexForInitialization(File index, Properties properties) {
+        try {
+            writePropertiesAtomically(index.toPath(), properties);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storeLock) {
+            return storedRules.containsKey(rule.getDescription());
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (storeLock) {
+            String description = rule.getDescription();
+            String existingFileName = storedRules.getProperty(description);
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                if (existingFileName == null) {
+                    return;
+                }
+                forgetRule(description, existingFileName);
+                return;
+            }
+
+            String fileName = existingFileName;
+            if (fileName == null) {
+                if (violations.isEmpty()) {
+                    fileName = deriveRuleFileName(description, false);
+                } else {
+                    fileName = deriveRuleFileName(description, false);
+                }
+                saveNewRule(description, fileName, violations);
+            } else {
+                saveExistingRule(fileName, violations);
+            }
+        }
+    }
+
+    private String deriveRuleFileName(String description, boolean initialization) {
+        String result;
+        try {
+            result = ruleViolationFileNameStrategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            if (initialization) {
+                throw new StoreInitializationFailedException(e);
+            }
+            throw new StoreUpdateFailedException(e);
+        }
+        if (result == null || result.trim().isEmpty()) {
+            String message = "RuleViolationFileNameStrategy did not return a file name for rule '" + description + "'";
+            if (initialization) {
+                throw new StoreInitializationFailedException(message);
+            }
+            throw new StoreUpdateFailedException(message);
+        }
+        return result;
+    }
+
+    private void saveNewRule(String description, String fileName, List<String> violations) {
+        Path target = validateWritableName(fileName, false);
+        if (pathObjectExists(target)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot store rule '%s': file '%s' is already owned by something else", description, fileName));
+        }
+
+        Properties next = copyOf(storedRules.snapshot());
+        next.setProperty(ensureUnixLineBreaks(description), ensureUnixLineBreaks(fileName));
+        Path violationTemp = null;
+        Path indexTemp = null;
+        boolean violationMoved = false;
+        try {
+            violationTemp = writeViolationsTemp(violations);
+            indexTemp = writePropertiesTemp(next);
+            moveWithoutReplacement(violationTemp, target);
+            violationMoved = true;
+            moveReplacing(indexTemp, getStoredRulesFile().toPath());
+            storedRules.replaceLoaded(next);
+        } catch (IOException e) {
+            if (violationMoved) {
+                deleteQuietly(target);
+            }
+            throw new StoreUpdateFailedException(e);
+        } finally {
+            deleteQuietly(violationTemp);
+            deleteQuietly(indexTemp);
+        }
+    }
+
+    private void saveExistingRule(String fileName, List<String> violations) {
+        Path target = validateWritableName(fileName, true);
+        Path violationTemp = null;
+        try {
+            violationTemp = writeViolationsTemp(violations);
+            moveReplacing(violationTemp, target);
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        } finally {
+            deleteQuietly(violationTemp);
+        }
+    }
+
+    private Path validateWritableName(String fileName, boolean mayAlreadyExist) {
+        Path path;
+        try {
+            Path fileNamePath = new File(fileName).toPath();
+            if (fileNamePath.isAbsolute() || fileNamePath.getNameCount() != 1
+                    || ".".equals(fileName) || "..".equals(fileName)
+                    || STORED_RULES_FILE_NAME.equals(fileName)) {
+                throw invalidWritableName(fileName);
+            }
+            path = storeFolder.toPath().resolve(fileNamePath);
+        } catch (RuntimeException e) {
+            if (e instanceof StoreUpdateFailedException) {
+                throw e;
+            }
+            throw invalidWritableName(fileName);
+        }
+
+        if (!mayAlreadyExist && pathObjectExists(path)) {
+            throw invalidWritableName(fileName);
+        }
+        if (mayAlreadyExist && pathObjectExists(path)) {
+            Path realTarget = realPath(path);
+            if (realTarget == null || !isDirectPath(realTarget)) {
+                throw invalidWritableName(fileName);
+            }
+            return realTarget;
+        }
+        if (!isDirectPath(path.getParent())) {
+            throw invalidWritableName(fileName);
+        }
+        return path;
+    }
+
+    private StoreUpdateFailedException invalidWritableName(String fileName) {
+        return new StoreUpdateFailedException(String.format(
+                "Refusing to write violation file '%s': it is not a new or directly-owned file in the store folder",
+                fileName));
+    }
+
+    private void forgetRule(String description, String fileName) {
+        Properties current = storedRules.snapshot();
+        boolean shared = sharesFileWithAnotherEntry(description, fileName, current);
+        Path source = pathFor(fileName);
+        boolean sourceExists = pathObjectExists(source);
+        Path indexTemp = null;
+        try {
+            Properties next = copyOf(current);
+            next.remove(ensureUnixLineBreaks(description));
+            indexTemp = writePropertiesTemp(next);
+
+            if (!shared && sourceExists) {
+                deleteOwnedFile(source);
+            }
+            moveReplacing(indexTemp, getStoredRulesFile().toPath());
+            storedRules.replaceLoaded(next);
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        } finally {
+            deleteQuietly(indexTemp);
+        }
+    }
+
+    private boolean sharesFileWithAnotherEntry(String description, String fileName, Properties properties) {
+        Path source = pathFor(fileName);
+        String identity = fileIdentity(source);
+        for (String otherDescription : properties.stringPropertyNames()) {
+            if (ensureUnixLineBreaks(description).equals(otherDescription)) {
+                continue;
+            }
+            String otherName = properties.getProperty(otherDescription);
+            if (fileName.equals(otherName)) {
+                return true;
+            }
+            if (identity != null && identity.equals(fileIdentity(pathFor(otherName)))) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private void deleteOwnedFile(Path source) throws IOException {
+        if (!pathObjectExists(source)) {
+            return;
+        }
+        if (!isDirectRegularFile(source)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot remove violation file '%s' without changing anything", source.getFileName()));
+        }
+        Path target = realPath(source);
+        if (target == null || !isDirectPath(target)) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Cannot remove violation file '%s' because it is outside the store folder", source.getFileName()));
+        }
+        Files.delete(target);
+        if (!target.equals(source) && Files.exists(source, LinkOption.NOFOLLOW_LINKS)) {
+            Files.delete(source);
+        }
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (storeLock) {
+            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(ruleDetailsFileName);
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(String ruleDetailsFileName) {
+        String violationsText = readStoreFile(ruleDetailsFileName);
+        if (isOnlyLineBreaks(violationsText)) {
+            return Collections.emptyList();
+        }
+        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(violationsText)
+                .map(this::unescape)
+                .collect(toList());
+    }
+
+    private String readStoreFile(String fileName) {
+        try {
+            String result = new String(toByteArray(new File(storeFolder, fileName)), UTF_8);
+            return ensureUnixLineBreaks(result);
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    private IntegrityReport inspect(Properties properties) {
+        List<EntryInfo> entries = new ArrayList<>();
+        for (String description : properties.stringPropertyNames()) {
+            String fileName = properties.getProperty(description);
+            String derived = deriveRuleFileName(description, true);
+            entries.add(new EntryInfo(description, fileName, derived));
+        }
+
+        Map<String, Integer> names = new HashMap<>();
+        Map<String, Integer> identities = new HashMap<>();
+        Map<String, Integer> derivedNames = new HashMap<>();
+        for (EntryInfo entry : entries) {
+            names.put(entry.fileName, count(names, entry.fileName));
+            if (entry.identity != null) {
+                identities.put(entry.identity, count(identities, entry.identity));
+            }
+            derivedNames.put(entry.derivedFileName, count(derivedNames, entry.derivedFileName));
+        }
+
+        for (EntryInfo entry : entries) {
+            entry.shared = names.get(entry.fileName) > 1
+                    || (entry.identity != null && identities.get(entry.identity) > 1);
+            entry.misplaced = !entry.fileName.equals(entry.derivedFileName);
+            entry.colliding = derivedNames.get(entry.derivedFileName) > 1;
+            entry.occupied = entry.misplaced && (isEscapingName(entry.derivedFileName)
+                    || pathObjectExists(pathFor(entry.derivedFileName))
+                    || recordsAnotherEntry(entries, entry, entry.derivedFileName));
+        }
+
+        List<File> unowned = findUnownedFiles(entries);
+        return new IntegrityReport(entries, unowned);
+    }
+
+    private int count(Map<String, Integer> counts, String key) {
+        Integer previous = counts.get(key);
+        return previous == null ? 1 : previous + 1;
+    }
+
+    private boolean recordsAnotherEntry(List<EntryInfo> entries, EntryInfo current, String fileName) {
+        for (EntryInfo entry : entries) {
+            if (entry != current && fileName.equals(entry.fileName)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private List<File> findUnownedFiles(List<EntryInfo> entries) {
+        List<String> recordedNames = entries.stream().map(entry -> entry.fileName).collect(toList());
+        List<File> result = new ArrayList<>();
+        try (DirectoryStream<Path> paths = Files.newDirectoryStream(storeFolder.toPath())) {
+            for (Path path : paths) {
+                if (STORED_RULES_FILE_NAME.equals(path.getFileName().toString())) {
+                    continue;
+                }
+                if (Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS)
+                        && !recordedNames.contains(path.getFileName().toString())) {
+                    result.add(path.toFile());
+                }
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+        result.sort(Comparator.comparing(File::getName));
+        return result;
+    }
+
+    private boolean repair(IntegrityReport report, Properties repaired) {
+        boolean changed = false;
+        List<EntryInfo> ordered = new ArrayList<>(report.entries);
+        ordered.sort(Comparator.comparing(entry -> entry.description));
+        for (EntryInfo entry : ordered) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken || entry.resolved) {
+                repaired.remove(entry.description);
+                try {
+                    if (entry.resolved && entry.directRegular) {
+                        deleteEntryFileForRepair(entry);
+                    } else {
+                        deleteBrokenLinkForRepair(entry);
+                    }
+                } catch (IOException e) {
+                    throw new StoreInitializationFailedException(e);
+                }
+                changed = true;
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                moveEntryForRepair(entry);
+                repaired.setProperty(entry.description, ensureUnixLineBreaks(entry.derivedFileName));
+                changed = true;
+            }
+        }
+        return changed;
+    }
+
+    private void deleteEntryFileForRepair(EntryInfo entry) throws IOException {
+        Path target = entry.target;
+        if (target != null && isDirectPath(target)) {
+            Files.deleteIfExists(target);
+        }
+        if (entry.sourceIsLink && pathObjectExists(entry.source)) {
+            Files.deleteIfExists(entry.source);
+        }
+    }
+
